def select_competitor(self, competitors):
    if not competitors:
        return None

    # Calculate the total fitness and number of competitors
    total_fitness = sum(max(comp['fitness'], 0) for comp in competitors)
    if total_fitness <= 0:
        return random.choice(competitors)

    # Sample a competitor based on fitness
    rand_val = random.random() * total_fitness
    cumulative_fitness = 0
    for competitor in competitors:
        cumulative_fitness += max(competitor['fitness'], 0)
        if rand_val <= cumulative_fitness:
            return competitor

    # If no competitor was selected, return a random one
    return random.choice(competitors)

def select_competitor(self, competitors):
    # Tournament selection
    tournament_size = 3
    tournament_competitors = random.sample(competitors, min(tournament_size, len(competitors)))
    tournament_winner = max(tournament_competitors, key=lambda x: x['fitness'] if x['fitness'] is not None else -1)

    # Random sampling from the archive and population
    archive_competitor = random.choice(list(self.archive.values()))
    population_competitor = random.choice(self.population)

    # Hybrid selection
    if random.random() < 0.5:
        return tournament_winner
    else:
        return max([archive_competitor, population_competitor], key=lambda x: x['fitness'] if x['fitness'] is not None else -1)

